// Des: Tests for every catalog job on the fake site (mock-tested, not live-verified)
// Flo: run each job live > assert what the site recorded > irreversible jobs refuse without --force > list jobs loop item by item
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-jobs-main-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig"); const pack = @import("ut-loca-pack.zig");
fn go(rig: *rigz.Rig, mode: task.Mode, name: []const u8, args: task.Args) !u32 { var cx = rig.ctx(mode); return jrun.run(&cx, jobs.find(name).?, args); }
fn must(rig: *rigz.Rig, prefix: []const u8) !void { if (!rig.waitPre(prefix, 4000)) { std.debug.print("missing record: {s}\n", .{prefix}); return error.TestUnexpectedResult; } }
test "catalog: every job has a unique name, known label keys, and needs only known args" { for (jobs.JOBS, 0..) |jb, ix| { for (jobs.JOBS[ix + 1 ..]) |oth| try std.testing.expect(!std.mem.eql(u8, jb.name, oth.name)); try std.testing.expect(jb.steps.len >= 2); try std.testing.expect(jb.steps[0].op == .goto); for (jb.steps) |tpl| { if (tpl.key.len > 0) try std.testing.expect(pack.known(tpl.key)); } } }
test "posts: photo, audience, poll, edit, comment, react, share, save" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.capz_post_dayz = 50; const pho = try rig.absOf("p.jpg"); try std.Io.Dir.cwd().writeFile(rig.iozz, .{ .sub_path = try std.fmt.allocPrint(rig.aren.allocator(), ".zig-cache/tmp/{s}/p.jpg", .{rig.tmpz.sub_path}), .data = "JPG" }); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-photo", .{ .text = "Photo post", .photo = pho })); try must(&rig, "photo|1"); try must(&rig, "post|Photo post"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-audience", .{ .text = "Friends only", .opt = "Friends" })); try must(&rig, "aud|Friends"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-poll", .{ .text = "Pick one", .title = "Red", .desc = "Blue" })); try must(&rig, "poll|Red|Blue"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-edit", .{ .url = "/posts/1", .text = "new text" })); try must(&rig, "btn|Save|new text|"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-comment", .{ .url = "/posts/1", .text = "Nice one" })); try must(&rig, "key|Write a comment=Nice one"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-react", .{ .url = "/posts/1" })); try must(&rig, "hov|React>Like"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-react", .{ .url = "/posts/2", .opt = "Love" })); try must(&rig, "hov|React>Love"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-share", .{ .url = "/posts/1" })); try must(&rig, "btn|Share now|"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-share-group", .{ .url = "/posts/1", .group = "Bike Club HN" })); try must(&rig, "btn|Bike Club HN|"); try must(&rig, "btn|Post|"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-save", .{ .url = "/posts/1" })); try must(&rig, "btn|Save post|"); }
test "irreversible jobs refuse without --force, then run: delete post, unfriend, block, leave group, cancel event" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const cases = [_]struct { name: []const u8, args: task.Args, rec: []const u8, cnf: []const u8 = "btn|Confirm|" }{ .{ .name = "post-delete", .args = .{ .url = "/posts/1" }, .rec = "btn|Delete post|", .cnf = "btn|Delete|" }, .{ .name = "friend-unfriend", .args = .{ .url = "/people/7" }, .rec = "btn|Unfriend|" }, .{ .name = "friend-block", .args = .{ .url = "/people/7" }, .rec = "btn|Block|" }, .{ .name = "group-leave", .args = .{ .url = "/groups/88/" }, .rec = "btn|Leave group|" }, .{ .name = "event-cancel", .args = .{ .url = "/events/1" }, .rec = "btn|Cancel event|" } }; for (cases) |cs| { try std.testing.expectError(error.NeedApprove, go(&rig, .live, cs.name, cs.args)); try std.testing.expect(!rig.hasRec(cs.rec)); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .force, cs.name, cs.args)); try must(&rig, cs.rec); try must(&rig, cs.cnf); } try std.testing.expectEqual(@as(i64, 5), try rig.store.actCnt("post", 0) + try rig.store.actCnt("frie", 0) + try rig.store.actCnt("grou", 0) + try rig.store.actCnt("evnt", 0)); }
test "friends and messenger: accept, decline, follow, unfollow, birthday wishes, requests, file" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectEqual(@as(u32, 3), try go(&rig, .live, "friend-accept", .{})); var tries: u32 = 0; while (rig.mock.recNum("item") < 3 and tries < 80) : (tries += 1) std.Io.sleep(rig.iozz, .fromMilliseconds(50), .awake) catch {}; try std.testing.expectEqual(@as(usize, 3), rig.mock.recNum("item")); try std.testing.expectEqual(@as(u32, 0), try go(&rig, .live, "friend-accept", .{})); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "friend-decline", .{})); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "friend-follow", .{ .url = "/people/7" })); try must(&rig, "btn|Follow|"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "friend-unfollow", .{ .url = "/people/7" })); try must(&rig, "btn|Unfollow|"); try std.testing.expectEqual(@as(u32, 2), try go(&rig, .live, "birthday-wish", .{ .text = "Happy birthday" })); tries = 0; while (rig.mock.recNum("key") < 2 and tries < 80) : (tries += 1) std.Io.sleep(rig.iozz, .fromMilliseconds(50), .awake) catch {}; try std.testing.expectEqual(@as(usize, 2), rig.mock.recNum("key")); try std.testing.expectEqual(@as(u32, 2), try go(&rig, .live, "msgr-accept", .{})); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "noti-mark", .{})); try must(&rig, "notimark|all"); const pho = try rig.absOf("f.txt"); try std.Io.Dir.cwd().writeFile(rig.iozz, .{ .sub_path = try std.fmt.allocPrint(rig.aren.allocator(), ".zig-cache/tmp/{s}/f.txt", .{rig.tmpz.sub_path}), .data = "hi" }); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "msgr-file", .{ .to = "42", .photo = pho })); try must(&rig, "mfile|1"); }
test "groups, pages, business suite, listings, events, stories, reels, profile" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectEqual(@as(u32, 2), try go(&rig, .live, "admin-approve", .{ .url = "/groups/88/" })); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "admin-decline", .{ .url = "/groups/88/" })); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .force, "admin-remove", .{ .url = "/groups/88/" })); try must(&rig, "btn|Remove post|"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "page-switch", .{ .url = "/pages/5/" })); try must(&rig, "btn|Switch now|"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .force, "page-hide", .{ .url = "/pages/5/" })); try must(&rig, "btn|Hide comment|"); rig.conf.base_bizz_main = try std.fmt.allocPrint(rig.aren.allocator(), "{s}", .{rig.base()}); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "biz-schedule", .{ .text = "Later post", .date = "2026-12-01", .time = "09:00" })); try must(&rig, "btn|Schedule|Later post|2026-12-01|09:00"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "market-edit", .{ .url = "/marketplace/item/1", .price = "250" })); try must(&rig, "btn|Save|250"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "event-create", .{ .title = "Bike meetup", .date = "2026-12-05", .desc = "Bring bikes" })); try must(&rig, "btn|Create event|Bike meetup|2026-12-05|Bring bikes"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "event-invite", .{ .url = "/events/1", .to = "Ann Lee" })); try must(&rig, "btn|Send invites|Ann Lee"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "event-respond", .{ .url = "/events/1" })); try must(&rig, "btn|Going|"); const pho = try rig.absOf("s.jpg"); try std.Io.Dir.cwd().writeFile(rig.iozz, .{ .sub_path = try std.fmt.allocPrint(rig.aren.allocator(), ".zig-cache/tmp/{s}/s.jpg", .{rig.tmpz.sub_path}), .data = "JPG" }); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "story-create", .{ .photo = pho })); try must(&rig, "btn|Share to story|"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "reel-create", .{ .photo = pho, .text = "My reel" })); try must(&rig, "btn|Share reel|My reel"); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "profile-bio", .{ .text = "New bio" })); try must(&rig, "btn|Save|New bio"); }
test "args are checked, repeats are skipped, caps apply per kind" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectError(error.BadUsage, go(&rig, .live, "post-edit", .{ .url = "/posts/1" })); try std.testing.expectError(error.BadUsage, go(&rig, .live, "event-create", .{ .title = "x" })); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "post-save", .{ .url = "/posts/1" })); try std.testing.expectEqual(@as(u32, 0), try go(&rig, .live, "post-save", .{ .url = "/posts/1" })); rig.conf.capz_stor_dayz = 1; const pho = try rig.absOf("s.jpg"); try std.Io.Dir.cwd().writeFile(rig.iozz, .{ .sub_path = try std.fmt.allocPrint(rig.aren.allocator(), ".zig-cache/tmp/{s}/s.jpg", .{rig.tmpz.sub_path}), .data = "JPG" }); _ = try go(&rig, .live, "story-create", .{ .photo = pho }); try std.testing.expectError(error.CapHit, go(&rig, .live, "reel-create", .{ .photo = pho, .text = "again" })); }
test "dry-run shows the plan and changes nothing for every job kind" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .dry, "post-comment", .{ .url = "/posts/1", .text = "x" })); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); try std.testing.expect(std.mem.find(u8, rig.sink.items, "dry-run: preview only") != null); }
